declarations.code:
template <std::size_t N>

std::bitset<N> operator&(const std::bitset<N> &lhs,

    const std::bitset<N> &rhs);

template <std::size_t N>

std::bitset<N> operator|(const std::bitset<N> &lhs,

    const std::bitset<N> &rhs);

template <std::size_t N>

std::bitset<N> operator^(const std::bitset<N> &lhs,

    const std::bitset<N> &rhs);

examples.code:
#include <bitset>
#include <iostream>

int main() {
    std::bitset<4> b1("0110");
    std::bitset<4> b2("0011");

    std::cout << "b1 & b2: " << (b1 & b2) << '\n';
    std::cout << "b1 | b2: " << (b1 | b2) << '\n';
    std::cout << "b1 ^ b2: " << (b1 ^ b2) << '\n';
}
